texts = ["yellow screw", "yellow nut", "red screw", "red nut", "white screw", "white nut"]
for text in texts:
    try:
        r = tools.vision_ground(camera="head", text=text, max_candidates=3)
    except Exception as e:
        print(text, "EXC", e)
