import json
from robot import tools
from ora_lib import frames_card, object_geometry

print(frames_card())
out = {}
queries = ["yellow nut","yellow screw","yellow bolt","red nut","red screw","red bolt",
           "white nut","white screw","white bolt","hex nut","threaded bolt"]
for cam in ("head",):
    for text in queries:
        try:
            r = tools.vision_ground(camera=cam, text=text, max_candidates=3)
        except Exception as e:
            print("EXC", cam, text, e); continue
        rows = []
        for c in r["result"].get("candidates", []):
            d = {"id": c["candidate_id"], "bbox": c["bbox_xyxy"], "score": c.get("backend_score"),
                 "centroid": c.get("mask_summary",{}).get("centroid_uv"),
                 "area": c.get("mask_summary",{}).get("pixel_count")}
            loc = c.get("localization") or {}
            d["center"] = loc.get("center_xyz_m"); d["extent"] = loc.get("extent_xyz_m")
            d["height"] = loc.get("height_above_support_m"); d["support_z"] = loc.get("support_z_m")
            d["largest_axis"] = loc.get("largest_extent_axis_world"); d["largest_extent"] = loc.get("largest_extent_m")
            d["pext"] = loc.get("principal_extents_m")
            rows.append(d)
        out.setdefault(cam, {})[text] = rows
        print("---", cam, text)
        for d in rows:
            print(json.dumps({k:(round(v,4) if isinstance(v,float) else v) for k,v in d.items()}, default=str))
with open("objs.json","w") as f: json.dump(out,f,indent=1,default=str)

