import json, numpy as np
from robot import query
from scipy.spatial.transform import Rotation
LOG = open("/work/planw_log.txt","a")
def log(*a):
    s=" ".join(str(x) for x in a); print(s); LOG.write(s+"\n"); LOG.flush()
def quat_for(approach, yaw_deg):
    a = np.array(approach,float); a/=np.linalg.norm(a)
    j = np.array([np.cos(np.radians(yaw_deg)), np.sin(np.radians(yaw_deg)), 0.0])
    j = j - (j@a)*a; j/=np.linalg.norm(j)
    return Rotation.from_matrix(np.column_stack([a,j,np.cross(a,j)])).as_quat().tolist()
nut = (0.0871,-0.0695); scr = (0.2514,-0.1674)
res = {}
for yaw in (0,30,60,90,122,152):
    q = quat_for([0,0,-1], yaw)
    for arm, xy, zs in (("right", nut, (0.926,0.966)), ("right", scr, (0.942,0.962,0.982))):
        poses = [[xy[0],xy[1],z,*q] for z in zs]
        rc = query("reach_check", arm=arm, poses=poses, interaction="precision")
        res[f"{arm}_{ 'nut' if xy==nut else 'screw' }_{yaw}"] = [(round(p[2],3), r.get("reachable"), r.get("reason")) for p,r in zip(poses, rc["results"])]
log(json.dumps(res, indent=0))

