"""Finalize: open both grippers fully, both arms home, settle, then verify + measure all nuts."""
import json, numpy as np
from robot import tools, handoff, ToolRefused
from ora_lib import current, Point
from geo2 import cloud_world
from geo import ground_pick
HOME={"left":np.array([-0.2995290756225586,-0.35229986906051636,0.921500027179718]),
      "right":np.array([0.3004709482192993,-0.35229986906051636,0.921500027179718])}
TOL=0.005; H_NUT=0.0191
LOG=open("/work/fin_log.txt","a")
def log(*a):
    s=" ".join(str(x) for x in a); print(s); LOG.write(s+"\n"); LOG.flush()
def opens():
    return {a: current().robot_facts["end_effectors"][a]["gripper"]["measured_opening_normalized"] for a in ("left","right")}
def eepos():
    return {a: np.array(current().pose(a).position.xyz) for a in ("left","right")}
try:
    for a in ("right","left"):
        for k in range(4):
            o=opens()[a]
            if o is not None and o>0.98: break
            r=tools.set_gripper(targets={a:"open"})
            log("open_%s_%d"%(a,k), json.dumps({"opening":r.measured_opening}))
    log("grip_after_open", json.dumps({a:round(v,4) if v is not None else None for a,v in opens().items()}))
    r=tools.return_home(arms=["left","right"])
    log("home", json.dumps({"ok":bool(r.ok),"status":r.status,"failure":r.failure_code}))
    r=tools.wait_ticks(ticks=10)
    log("wait", json.dumps({"ok":bool(r.ok),"status":r.status}))
    o=opens(); p=eepos()
    miss={a: round(float(np.linalg.norm(p[a]-HOME[a])),5) for a in ("left","right")}
    log("VERIFY", json.dumps({"grip":{a:round(v,4) if v is not None else None for a,v in o.items()},"miss_m":miss}))
    # measure all nuts one more time
    def state(cam,color):
        o_=current()
        f=ground_pick(cam,f"{color} screw","screw") or ground_pick(cam,f"{color} nut","nut")
        if f is None: return None
        pts=cloud_world(o_,cam,f["target_ref"]); z=pts[:,2]
        t=float(np.percentile(z,99.9)); h=pts[z>t-0.003][:,:2].mean(0)
        rr=np.linalg.norm(pts[:,:2]-h,axis=1)
        ring=(rr>0.0125)&(rr<0.0180); tip=(rr<0.0064)
        d={"cam":cam,"ring_z":None,"tip_z":None}
        if ring.sum()>40: d["ring_z"]=round(float(np.median(pts[ring][:,2])),4)
        if tip.sum()>25: d["tip_z"]=round(float(np.median(pts[tip][:,2])),4)
        if d["ring_z"] and d["tip_z"]: d["below_tip_mm"]=round((d["tip_z"]-d["ring_z"]+H_NUT)*1000,1)
        return d
    for color,cam in (("yellow","head"),("red","head"),("white","head")):
        log(color, json.dumps(state(cam,color)))
    handoff("finalized", grip={a:round(v,4) if v is not None else None for a,v in o.items()}, miss_m=miss)
except ToolRefused as e:
    handoff("tool refused",code=e.code,answer=e.answer,name=e.name)
